      "id": 1,
      "claim": "Sexual reproduction combines genetic material from two parents via the fusion of gametes.",
      "evidence": "Biology definition: sexual reproduction = union of haploid gametes (egg and sperm) from two individuals producing a diploid zygote.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Asexual reproduction produces offspring from a single parent without gamete fusion.",
      "evidence": "Biology definition: asexual reproduction = mitotic division, binary fission, budding, etc., yielding clones of the parent.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Meiosis and fertilization generate new allele combinations through recombination and independent assortment.",
      "evidence": "Genetics: meiosis halves chromosome number and shuffles alleles; fertilization restores diploidy, mixing two parental genomes.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 4,
      "claim": "This recombination creates far greater genetic variation per generation than the limited variation produced only by random mutations in asexual reproduction (mutation rate ≈10⁻⁸ per base per generation, whereas recombination reshuffles thousands of loci each generation).",
      "evidence": "Population‑genetics data show mutation rates are orders of magnitude lower than the number of new genotype combinations generated by meiotic recombination.",
      "weight": 0.25,
      "depends_on": [2, 3]
    },
    {
      "id": 5,
      "claim": "Greater genetic variation enhances a population’s ability to adapt to environmental changes and resist diseases, providing an evolutionary advantage.",
      "evidence": "Natural‑selection principle: diverse phenotypes increase the chance that some individuals survive novel stresses.",
      "weight": 0.15,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Option (A) – “There is greater variation among the offspring” – directly describes this primary advantage; the other options describe traits of asexual reproduction or are not advantages of sexual reproduction.",
      "evidence": "Mapping of the conclusion in step 5 to the answer choices.",
      "weight": 0.05,
      "depends_on": [5]
    }
  ],
  "answer": "A",
  "confidence": 0.99,
  "considered": [
    {
      "answer": "B",
      "reason_rejected": "Identical offspring are characteristic of asexual reproduction, not an advantage of sexual reproduction."
    },
    {
      "answer": "C",
      "reason_rejected": "Needing only one parent is an advantage of asexual reproduction; sexual reproduction requires two parents."
    },
    {
      "answer": "D",
      "reason_rejected": "Sexual reproduction explicitly requires sex cells (gametes); lacking them is a trait of asexual reproduction."
    }
